1	// Room bookings page script. Classic script: runs its setup at once.
2	(function () {
3	  'use strict';
4	
5	  const NO_REPLY = 'Could not reach the server.';
6	  const FALLBACK = 'Request failed.';
7	
8	  const form = document.getElementById('booking-form');
9	  const roomSelect = document.getElementById('room');
10	  const titleInput = document.getElementById('title');
11	  const dateInput = document.getElementById('date');
12	  const startInput = document.getElementById('start');
13	  const endInput = document.getElementById('end');
14	  const bookButton = document.getElementById('book');
15	  const filterInput = document.getElementById('filter-date');
16	  const showAllButton = document.getElementById('show-all');
17	  const list = document.getElementById('booking-list');
18	  const errorBox = document.getElementById('error');
19	
20	  let listGeneration = 0;
21	
22	  // Sends a request. Resolves to { reached: false } when there is no usable
23	  // reply, else { reached: true, status, body }. A 204 body is never read.
24	  async function send(url, options) {
25	    let res;
26	    try {
27	      res = await fetch(url, options);
28	    } catch (err) {
29	      return { reached: false };
30	    }
31	    if (res.status === 204) {
32	      return { reached: true, status: 204, body: null };
33	    }
34	    try {
35	      const body = await res.json();
36	      return { reached: true, status: res.status, body: body };
37	    } catch (err) {
38	      return { reached: false };
39	    }
40	  }
41	
42	  function isObject(value) {
43	    return typeof value === 'object' && value !== null && !Array.isArray(value);
44	  }
45	
46	  function errorMessage(body) {
47	    return isObject(body) && typeof body.error === 'string' ? body.error : FALLBACK;
48	  }
49	
50	  function showError(text) {
51	    errorBox.textContent = text;
52	  }
53	
54	  function showFailure(result) {
55	    showError(result.reached ? errorMessage(result.body) : NO_REPLY);
56	  }
57	
58	  async function loadRooms() {
59	    const result = await send('/api/rooms', { method: 'GET' });
60	    if (!result.reached || result.status !== 200) {
61	      showFailure(result);
62	      return;
63	    }
64	    const rooms = isObject(result.body) && Array.isArray(result.body.rooms) ? result.body.rooms : [];
65	    const options = rooms.map(function (name) {
66	      const option = document.createElement('option');
67	      option.value = name;
68	      option.textContent = name;
69	      return option;
70	    });
71	    roomSelect.replaceChildren(...options);
72	  }
73	
74	  function bookingItem(booking) {
75	    const item = document.createElement('li');
76	    const cancel = document.createElement('button');
77	    cancel.type = 'button';
78	    cancel.textContent = 'Cancel';
79	    cancel.addEventListener('click', function () {
80	      cancelBooking(booking.id, cancel);
81	    });
82	    const text = booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
83	      booking.room + ': ' + booking.title;
84	    item.append(text, cancel);
85	    return item;
86	  }
87	
88	  function emptyItem() {
89	    const item = document.createElement('li');
90	    item.append('No bookings.');
91	    return item;
92	  }
93	
94	  function renderBookings(bookings) {
95	    const items = bookings.length === 0 ? [emptyItem()] : bookings.map(bookingItem);
96	    list.replaceChildren(...items);
97	  }
98	
99	  async function loadList() {
100	    listGeneration += 1;
101	    const generation = listGeneration;
102	    const filter = filterInput.value;
103	    const url = filter === '' ? '/api/bookings' : '/api/bookings?date=' + filter;
104	    const result = await send(url, { method: 'GET' });
105	    if (generation !== listGeneration) {
106	      return;
107	    }
108	    if (!result.reached || result.status !== 200) {
109	      showFailure(result);
110	      return;
111	    }
112	    if (!isObject(result.body) || !Array.isArray(result.body.bookings)) {
113	      showError(FALLBACK);
114	      return;
115	    }
116	    renderBookings(result.body.bookings);
117	  }
118	
119	  async function submitBooking(event) {
120	    event.preventDefault();
121	    if (bookButton.disabled) {
122	      return;
123	    }
124	    bookButton.disabled = true;
125	    const payload = {
126	      room: roomSelect.value,
127	      title: titleInput.value,
128	      date: dateInput.value,
129	      start: startInput.value,
130	      end: endInput.value,
131	    };
132	    const result = await send('/api/bookings', {
133	      method: 'POST',
134	      headers: { 'Content-Type': 'application/json' },
135	      body: JSON.stringify(payload),
136	    });
137	    bookButton.disabled = false;
138	    if (result.reached && result.status === 201) {
139	      titleInput.value = '';
140	      showError('');
141	      loadList();
142	      return;
143	    }
144	    showFailure(result);
145	  }
146	
147	  async function cancelBooking(id, button) {
148	    button.disabled = true;
149	    const result = await send('/api/bookings/' + id, { method: 'DELETE' });
150	    button.disabled = false;
151	    if (!result.reached) {
152	      showError(NO_REPLY);
153	      return;
154	    }
155	    if (result.status === 204) {
156	      showError('');
157	    } else {
158	      showError(errorMessage(result.body));
159	    }
160	    loadList();
161	  }
162	
163	  function showAll() {
164	    filterInput.value = '';
165	    loadList();
166	  }
167	
168	  form.addEventListener('submit', submitBooking);
169	  filterInput.addEventListener('change', loadList);
170	  showAllButton.addEventListener('click', showAll);
171	
172	  loadRooms();
173	  loadList();
174	})();
