2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Room bookings</title>
7	<style>
8	  :root {
9	    --ink: #1d232b;
10	    --muted: #5b6672;
11	    --line: #d5dbe1;
12	    --paper: #f6f4ef;
13	    --card: #ffffff;
14	    --accent: #1f5f8b;
15	    --danger: #a12a2a;
16	  }
17	  * { box-sizing: border-box; }
18	  body {
19	    margin: 0;
20	    padding: 2rem 1rem 4rem;
21	    font: 16px/1.5 system-ui, sans-serif;
22	    color: var(--ink);
23	    background: var(--paper);
24	  }
25	  main { max-width: 42rem; margin: 0 auto; }
26	  h1 { font-size: 1.75rem; letter-spacing: -0.01em; margin: 0 0 1.5rem; }
27	  h2 { font-size: 1.1rem; margin: 2rem 0 0.75rem; }
28	  form, .filters {
29	    display: grid;
30	    gap: 0.75rem 1rem;
31	    grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
32	    align-items: end;
33	    padding: 1rem;
34	    background: var(--card);
35	    border: 1px solid var(--line);
36	    border-radius: 0.5rem;
37	  }
38	  .field { display: flex; flex-direction: column; gap: 0.25rem; }
39	  label { font-size: 0.85rem; font-weight: 600; color: var(--muted); }
40	  input, select, button { font: inherit; }
41	  input, select {
42	    padding: 0.4rem 0.5rem;
43	    border: 1px solid var(--line);
44	    border-radius: 0.375rem;
45	    background: #fff;
46	  }
47	  button {
48	    padding: 0.45rem 0.9rem;
49	    border: 1px solid var(--accent);
50	    border-radius: 0.375rem;
51	    background: var(--accent);
52	    color: #fff;
53	    cursor: pointer;
54	  }
55	  button[type="button"] { background: #fff; color: var(--accent); }
56	  button:disabled { opacity: 0.55; cursor: not-allowed; }
57	  :focus-visible { outline: 3px solid #f2b134; outline-offset: 2px; }
58	  #error { min-height: 1.5em; margin: 1rem 0 0; color: var(--danger); font-weight: 600; }
59	  #booking-list { list-style: none; margin: 0; padding: 0; }
60	  #booking-list li {
61	    display: flex;
62	    justify-content: space-between;
63	    align-items: center;
64	    gap: 1rem;
65	    padding: 0.6rem 0.75rem;
66	    border-bottom: 1px solid var(--line);
67	    overflow-wrap: anywhere;
68	  }
69	</style>
70	</head>
71	<body>
72	<main>
73	  <h1>Room bookings</h1>
74	
75	  <form id="booking-form" novalidate>
76	    <div class="field">
77	      <label for="room">Room</label>
78	      <select id="room" name="room"></select>
79	    </div>
80	    <div class="field">
81	      <label for="title">Title</label>
82	      <input type="text" id="title" name="title">
83	    </div>
84	    <div class="field">
85	      <label for="date">Date</label>
86	      <input type="date" id="date" name="date">
87	    </div>
88	    <div class="field">
89	      <label for="start">Start</label>
90	      <input type="time" id="start" name="start">
91	    </div>
92	    <div class="field">
93	      <label for="end">End</label>
94	      <input type="time" id="end" name="end">
95	    </div>
96	    <button type="submit" id="book">Book</button>
97	  </form>
98	
99	  <p id="error" role="alert"></p>
100	
101	  <h2>Bookings</h2>
102	  <div class="filters">
103	    <div class="field">
104	      <label for="filter-date">Show date</label>
105	      <input type="date" id="filter-date">
106	    </div>
107	    <button type="button" id="show-all">Show all</button>
108	  </div>
109	  <ul id="booking-list"></ul>
110	</main>
111	<script src="/app.js"></script>
112	</body>
113	</html>
